UPDATE careers SET category_id=(SELECT id FROM career_categories WHERE code='DEF') WHERE code='DEF001';

SELECT c.id, t.id, 4 FROM careers c JOIN career_categories cc ON cc.id=c.category_id JOIN traits t ON t.code = CASE cc.code WHEN 'TECH' THEN 'TEC' WHEN 'HLTH' THEN 'SOC' WHEN 'BUS' THEN 'LDR' WHEN 'ART' THEN 'CRT' WHEN 'GOV' THEN 'LDR' WHEN 'EDU' THEN 'COM' WHEN 'SCI' THEN 'SCI' WHEN 'LAW' THEN 'COM' WHEN 'DEF' THEN 'DIS' WHEN 'SPT' THEN 'PHY' WHEN 'TRD' THEN 'HND' WHEN 'AGR' THEN 'NAT' WHEN 'HOS' THEN 'SOC' WHEN 'MEDI' THEN 'STO' END ON CONFLICT (career_id, trait_id) DO NOTHING;
SELECT c.id, s.id, 4 FROM careers c JOIN career_categories cc ON cc.id=c.category_id JOIN skills s ON s.code = CASE cc.code WHEN 'TECH' THEN 'SK011' WHEN 'HLTH' THEN 'SK064' WHEN 'BUS' THEN 'SK046' WHEN 'ART' THEN 'SK031' WHEN 'GOV' THEN 'SK008' WHEN 'EDU' THEN 'SK071' WHEN 'SCI' THEN 'SK091' WHEN 'LAW' THEN 'SK021' WHEN 'DEF' THEN 'SK081' WHEN 'SPT' THEN 'SK081' WHEN 'TRD' THEN 'SK014' WHEN 'AGR' THEN 'SK087' WHEN 'HOS' THEN 'SK021' WHEN 'MEDI' THEN 'SK021' END ON CONFLICT (career_id, skill_id) DO NOTHING;
SELECT c.id, s.id, 4 FROM careers c JOIN career_categories cc ON cc.id=c.category_id JOIN subjects s ON s.code = CASE cc.code WHEN 'TECH' THEN 'SUB005' WHEN 'HLTH' THEN 'SUB004' WHEN 'BUS' THEN 'SUB007' WHEN 'ART' THEN 'SUB009' WHEN 'GOV' THEN 'SUB010' WHEN 'EDU' THEN 'SUB008' WHEN 'SCI' THEN 'SUB002' WHEN 'LAW' THEN 'SUB008' WHEN 'DEF' THEN 'SUB011' WHEN 'SPT' THEN 'SUB011' WHEN 'TRD' THEN 'SUB002' WHEN 'AGR' THEN 'SUB012' WHEN 'HOS' THEN 'SUB007' WHEN 'MEDI' THEN 'SUB009' END ON CONFLICT (career_id, subject_id) DO NOTHING;

SELECT c.id, 'Standard route', 'Class 10 → Relevant stream or training → Qualification → ' || c.name, 'STANDARD', 48, 'Varies', 'Check institution requirements', 'Varies', false FROM careers c WHERE NOT EXISTS (SELECT 1 FROM routes r WHERE r.career_id=c.id);
SELECT r.id, 1, 'Class 10', 'Complete school and explore the relevant subjects.' FROM routes r WHERE NOT EXISTS (SELECT 1 FROM route_steps rs WHERE rs.route_id=r.id);
SELECT r.id, 2, 'Education or training', 'Choose the route and qualification that fit your goals and circumstances.' FROM routes r WHERE NOT EXISTS (SELECT 1 FROM route_steps rs WHERE rs.route_id=r.id);
SELECT r.id, 3, c.name, 'Build skills, experience and a portfolio where relevant.' FROM routes r JOIN careers c ON c.id=r.career_id WHERE NOT EXISTS (SELECT 1 FROM route_steps rs WHERE rs.route_id=r.id);
